// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        bool ok;
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.assume(ok);

        vm.prank(actor);
        bool ret;
        try c.setOwner(newOwner) returns (bool r) {
            ret = r;
        } catch {
            revert("unexpected revert when owner calls setOwner");
        }

        assertTrue(ret);
    }
}
